"""Run the transpiler over ifcopenshell.util and ifcopenshell.api and write TRACKING.md."""

import argparse
import ast
import collections
import re
import sys
from pathlib import Path

import yaml

from transpile import Transpiler, build_index, module_name

HERE = Path(__file__).parent
PACKAGE = HERE.parent / "ifcopenshell-python" / "ifcopenshell"
TESTS = HERE.parent / "ifcopenshell-python" / "test"
STAGES = ["blocked", "partial", "transpiles", "typecheck", "parity", "shipped"]
# Later stages mean translation is finished; partial is still underway.
DONE_STAGES = {"transpiles", "typecheck", "parity", "shipped"}
STATUS_MARK = {"blocked": "🔴", "partial": "🟠", "done": "🟢"}
PORT_MARK = {"generated": "🤖", "manual": "✍️", "mixed": "🔀", "skip": "⏭️"}
# Host, grammar, and geometry libraries. Date and matrix helpers stay on the
# generated path; these do not get a reusable transpile rule.
HAND_DEPS = {
    "lark", "shapely", "mathutils", "bpy", "bonsai", "networkx",
    "bs4", "lxml", "markdown", "requests", "server",
}
SKIPPED_IMPORTS = {"__future__", "typing", "collections", "collections.abc", "ifcopenshell", "TYPE_CHECKING"}


def blocker_key(message):
    """Group a 'No rules rule at line N: code' message by the construct that failed."""
    code = re.sub(r"^No \w+ rule at line \S+: ", "", message)
    if code.startswith(("import ", "from ")):
        return " ".join(code.split()[:2])
    return code.split("(")[0][:60]


def measure(compiler, path):
    source = path.read_text(encoding="utf-8")
    module = ast.parse(source)
    functions = [n.name for n in module.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))]
    imports = set()
    geom = False
    for node in ast.walk(module):
        if isinstance(node, ast.Import):
            imports.update(a.name for a in node.names)
            geom = geom or any(a.name == "geom" or a.name.startswith("ifcopenshell.geom") for a in node.names)
        elif isinstance(node, ast.ImportFrom) and node.module:
            imports.add(node.module)
            geom = geom or node.module == "ifcopenshell.geom" or node.module.startswith("ifcopenshell.geom.")
            geom = geom or (node.module == "ifcopenshell" and any(a.name == "geom" for a in node.names))
    external = sorted(
        {i.split(".")[0] for i in imports if not i.startswith("ifcopenshell")} - SKIPPED_IMPORTS
    )
    blockers = []
    try:
        compiler.translate(source, module_name(path))
        translated = len(functions) - len(compiler.unsupported)
        blockers = [blocker_key(d.split(": ", 1)[1]) for d in compiler.unsupported]
        module_blocker = None
    except Exception as error:  # A module-level construct stops the whole file.
        translated = 0
        module_blocker = blocker_key(str(error)) if isinstance(error, ValueError) else type(error).__name__
        blockers = [module_blocker]
    return {
        "lines": source.count("\n") + 1,
        "functions": len(functions),
        "translated": translated,
        "external": external,
        "geom": geom,
        "module_blocker": module_blocker,
        "blockers": blockers,
    }


def stage(row, manual):
    if manual in STAGES:
        return manual
    if row["translated"] == 0:
        return "blocked"
    return "transpiles" if row["translated"] == row["functions"] else "partial"


def status_kind(name):
    """Map a stage name to blocked, partial, or done."""
    if name in DONE_STAGES:
        return "done"
    if name == "partial":
        return "partial"
    return "blocked"


def pct(done, total):
    return f"{done}/{total} ({100 * done // total if total else 0}%)"


def mark(kind, text):
    return f"{STATUS_MARK[kind]} {text}"


def mark_stage(name):
    return mark(status_kind(name), name)


def mark_ratio(done, total):
    if not total or done == 0:
        kind = "blocked"
    elif done == total:
        kind = "done"
    else:
        kind = "partial"
    return mark(kind, pct(done, total))


def mark_blocked_files(count):
    return mark("done" if count == 0 else "blocked", str(count))


def mark_blocker(blocker):
    if not blocker:
        return "-"
    return mark("blocked", f"`{blocker}`")


def hand_reasons(row):
    reasons = [name for name in row["external"] if name in HAND_DEPS]
    if row["geom"]:
        reasons.append("ifcopenshell.geom")
    return reasons


def format_port(kind, detail=""):
    text = f"{PORT_MARK[kind]} {kind}"
    if detail:
        text += f" · {detail}"
    return text


def module_port(tier, row, override):
    """Generated by the transpiler, hand-ported, or a mix of both."""
    reasons = hand_reasons(row)
    if override in PORT_MARK:
        kind = override
    elif str(tier) == "skip":
        kind = "skip"
    elif str(tier) == "4":
        kind = "mixed"
    elif str(tier) == "5" or reasons:
        kind = "manual"
    else:
        kind = "generated"
    detail = ", ".join(reasons) if kind in {"manual", "mixed"} else ""
    return format_port(kind, detail)


def file_port(row):
    reasons = hand_reasons(row)
    if not reasons:
        return format_port("generated"), "generated"
    return format_port("manual", ", ".join(reasons)), "manual"


def package_port(entries, override):
    """entries are (kind, reasons) for each file in the package."""
    kinds = [kind for kind, _reasons in entries]
    manual_count = kinds.count("manual")
    if override in PORT_MARK:
        kind = override
    elif manual_count == 0:
        kind = "generated"
    elif manual_count == len(kinds):
        kind = "manual"
    else:
        kind = "mixed"
    reasons = sorted({reason for kind, reasons in entries if kind == "manual" for reason in reasons})
    if kind == "manual" and reasons and manual_count == len(kinds):
        detail = ", ".join(reasons)
    elif kind == "mixed" and manual_count:
        detail = f"{manual_count} manual"
        if reasons:
            detail += f" ({', '.join(reasons)})"
    else:
        detail = ""
    return format_port(kind, detail)


def table(headers, rows):
    lines = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    lines += ["| " + " | ".join(str(c) for c in row) + " |" for row in rows]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--rules", type=Path, default=HERE / "ts.yaml")
    parser.add_argument("-o", "--output", type=Path, default=HERE / "TRACKING.md")
    args = parser.parse_args()
    tracking = yaml.safe_load((HERE / "tracking.yaml").read_text(encoding="utf-8"))
    compiler = Transpiler(args.rules, build_index())
    blocker_counts = collections.Counter()

    util_rows = []
    for path in sorted((PACKAGE / "util").glob("*.py")):
        if path.stem == "__init__":
            continue
        row = measure(compiler, path)
        blocker_counts.update(row["blockers"])
        info = tracking["util"].get(path.stem, {})
        test = TESTS / "util" / f"test_{path.stem}.py"
        tier = info.get("tier", "?")
        util_rows.append(
            (path.stem, tier, stage(row, info.get("stage")), row, test.exists(), info.get("notes", ""),
             module_port(tier, row, info.get("port")))
        )

    api_rows = []
    api_files = collections.defaultdict(list)
    for package in sorted(p for p in (PACKAGE / "api").iterdir() if (p / "__init__.py").exists()):
        totals = collections.Counter()
        external = set()
        blocked_files = 0
        files = [p for p in sorted(package.glob("*.py")) if p.stem != "__init__"]
        for path in files:
            row = measure(compiler, path)
            blocker_counts.update(row["blockers"])
            totals.update(lines=row["lines"], functions=row["functions"], translated=row["translated"])
            external.update(row["external"])
            blocked_files += row["module_blocker"] is not None
            tested = (TESTS / "api" / package.name / f"test_{path.stem}.py").exists()
            label, kind = file_port(row)
            api_files[package.name].append((path.stem, row, tested, label, kind))
        tests = len(list((TESTS / "api" / package.name).glob("test_*.py")))
        info = tracking["api"].get(package.name, {})
        entries = [(item[4], hand_reasons(item[1])) for item in api_files[package.name]]
        api_rows.append(
            (package.name, info.get("tier", tracking["api_default_tier"]), len(files), totals, blocked_files, sorted(external), tests, info.get("notes", ""),
             package_port(entries, info.get("port")))
        )

    legend = " ".join(f"{emoji} {label}" for label, emoji in (
        ("done", STATUS_MARK["done"]),
        ("in progress", STATUS_MARK["partial"]),
        ("blocked", STATUS_MARK["blocked"]),
    ))
    port_legend = " ".join(f"{PORT_MARK[kind]} {kind}" for kind in ("generated", "manual", "mixed", "skip"))

    api_file_count = sum(len(files) for files in api_files.values())
    api_by_package = sorted(api_rows, key=lambda r: (str(r[1]), r[0]))

    def api_file_table(name):
        return table(
            ["File", "Port", "Translated", "Lines", "Python test", "Module blocker"],
            [
                (
                    f"`{stem}`", port, mark_ratio(r["translated"], r["functions"]), r["lines"],
                    "yes" if tested else "no", mark_blocker(r["module_blocker"]),
                )
                for stem, r, tested, port, _kind in api_files[name]
            ],
        )

    util_total = sum(r[3]["functions"] for r in util_rows)
    util_done = sum(r[3]["translated"] for r in util_rows)
    api_total = sum(r[3]["functions"] for r in api_rows)
    api_done = sum(r[3]["translated"] for r in api_rows)
    stages = collections.Counter(r[2] for r in util_rows)

    out = [
        "<!-- This file was generated with the assistance of an AI coding tool. -->",
        "<!-- Generated by src/transpiler/status.py from tracking.yaml. Do not edit by hand. -->",
        "",
        "# Transpilation tracking",
        "",
        f"Rules: `{args.rules.name}`. Regenerate with `python src/transpiler/status.py`. See [PLAN.md](PLAN.md) for stages and tiers.",
        "",
        legend,
        "",
        port_legend,
        "",
        "## Summary",
        "",
        table(
            ["Scope", "Modules", "Functions/classes translated", "Lines"],
            [
                ("util", len(util_rows), mark_ratio(util_done, util_total), sum(r[3]["lines"] for r in util_rows)),
                ("api", f"{len(api_rows)} packages, {api_file_count} files", mark_ratio(api_done, api_total), sum(r[3]["lines"] for r in api_rows)),
            ],
        ),
        "",
        "util stages: " + ", ".join(f"{mark_stage(s)} {stages[s]}" for s in STAGES if stages[s]),
        "",
        "## Top blockers",
        "",
        "First unsupported construct per function, or per module when it stops the whole file. Fixing a construct near the top unblocks the most code.",
        "",
        table(["Construct", "Occurrences"], [(f"`{k}`", v) for k, v in blocker_counts.most_common(25)]),
        "",
        "## util",
        "",
        table(
            ["Module", "Tier", "Port", "Stage", "Translated", "Lines", "External deps", "Python tests", "Module blocker", "Notes"],
            [
                (
                    f"`{name}`", tier, port, mark_stage(st), mark_ratio(r["translated"], r["functions"]), r["lines"],
                    ", ".join(r["external"]) or "-", "yes" if test else "no",
                    mark_blocker(r["module_blocker"]), notes,
                )
                for name, tier, st, r, test, notes, port in sorted(util_rows, key=lambda r: (str(r[1]), r[0]))
            ],
        ),
        "",
        "## api",
        "",
        table(
            ["Package", "Tier", "Port", "Files", "Translated", "Files blocked at module level", "Lines", "External deps", "Python test files", "Notes"],
            [
                (
                    f"`{name}`", tier, port, files, mark_ratio(t["translated"], t["functions"]),
                    mark_blocked_files(blocked), t["lines"],
                    ", ".join(external) or "-", tests, notes,
                )
                for name, tier, files, t, blocked, external, tests, notes, port in api_by_package
            ],
        ),
        "",
        "## api files",
        "",
    ]
    for name, *_rest in api_by_package:
        out += [f"### `{name}`", "", api_file_table(name), ""]
    args.output.write_text("\n".join(out), encoding="utf-8")
    print(f"util {pct(util_done, util_total)}, api {pct(api_done, api_total)} -> {args.output}", file=sys.stderr)


if __name__ == "__main__":
    main()
